<?php
$services=db()->query("SELECT id,name,price,duration_minutes FROM services WHERE status='active' ORDER BY name")->fetchAll();$customers=db()->query("SELECT id,full_name,customer_code FROM customers WHERE status='active' ORDER BY full_name")->fetchAll();$therapists=db()->query("SELECT id,full_name FROM therapists WHERE status='active' ORDER BY full_name")->fetchAll();
$activeAppts=db()->query("SELECT a.id,a.appointment_code,c.full_name customer_name,s.name service_name,a.customer_id,a.service_id,a.therapist_id FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id WHERE a.appointment_date=CURDATE() AND (a.status IN ('checked_in','in_session') OR (a.status='completed' AND a.payment_status<>'paid')) ORDER BY a.appointment_date,a.start_time")->fetchAll();
$selectedAppt=(int)($_GET['appointment_id']??0);$appt=null;if($selectedAppt){$q=db()->prepare("SELECT * FROM appointments WHERE id=? AND (status IN ('checked_in','in_session') OR (status='completed' AND payment_status<>'paid'))");$q->execute([$selectedAppt]);$appt=$q->fetch();}
?>
<div class="page-heading"><div><div class="eyebrow">Checkout</div><h1>Point of sale</h1><p>Record a service sale and issue a receipt after payment.</p></div><a href="<?=h(app_page_url('transactions'))?>" class="btn btn-outline-secondary"><i class="bi bi-receipt me-1"></i>Transactions</a></div>
<div class="row g-3"><div class="col-lg-8"><div class="card"><div class="card-header">Sale details</div><div class="card-body"><form method="post" id="posForm"><?=csrf_field()?><input type="hidden" name="action" value="checkout"><div class="row g-3"><div class="col-md-6"><label class="form-label">Link appointment (optional)</label><select class="form-select" name="appointment_id" id="appointmentSelect"><option value="">New sale / no appointment</option><?php foreach($activeAppts as $a):?><option value="<?=$a['id']?>" data-customer="<?=$a['customer_id']?>" data-service="<?=$a['service_id']?>" data-therapist="<?=$a['therapist_id']?>" <?=selected($selectedAppt,$a['id'])?>><?=h($a['appointment_code'])?> · <?=h($a['customer_name'])?> / <?=h($a['service_name'])?></option><?php endforeach;?></select><div class="form-text">Linking a checked-in appointment completes it and records the session.</div></div><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" id="customerSelect"><option value="">Guest / no profile</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=selected($appt['customer_id']??'', $c['id'])?>><?=h($c['full_name'])?> · <?=h($c['customer_code'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Service *</label><select class="form-select" name="service_id" data-price-source required id="serviceSelect"><?php foreach($services as $s):?><option value="<?=$s['id']?>" data-price="<?=$s['price']?>" <?=selected($appt['service_id']??($services[0]['id']??''),$s['id'])?>><?=h($s['name'])?> · <?=money($s['price'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Therapist</label><select class="form-select" name="therapist_id" id="therapistSelect"><option value="">Not assigned</option><?php foreach($therapists as $t):?><option value="<?=$t['id']?>" <?=selected($appt['therapist_id']??'', $t['id'])?>><?=h($t['full_name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Quantity</label><input class="form-control" type="number" min="1" max="50" value="1" name="quantity" data-qty></div><div class="col-md-4"><label class="form-label">Discount (₱)</label><input class="form-control" type="number" min="0" step="0.01" value="0" name="discount" data-discount></div><div class="col-md-4"><label class="form-label">Payment method</label><select class="form-select" name="payment_method"><option value="cash">Cash</option><option value="gcash">GCash</option><option value="bank_transfer">Bank transfer</option><option value="other">Other</option></select></div><div class="col-md-6"><label class="form-label">Amount received (₱) *</label><input class="form-control" type="number" step="0.01" min="0" name="amount_received" data-received required placeholder="Enter amount received"></div><div class="col-md-6"><label class="form-label">Change due</label><div class="form-control bg-light fw-bold" data-change-out>₱0.00</div></div></div><hr class="my-4"><div class="d-flex justify-content-between"><span class="text-muted">Subtotal</span><strong data-subtotal-out>₱0.00</strong></div><div class="d-flex justify-content-between fs-5 mt-2"><span class="fw-bold">Total due</span><strong class="text-success" data-total-out>₱0.00</strong></div><div class="alert alert-light border mt-3 mb-0 small"><i class="bi bi-shield-check me-1"></i>Checkout is blocked when the amount received is below the total. Final prices are taken from the service catalog on the server.</div><button class="btn btn-primary w-100 mt-4 py-2" type="submit"><i class="bi bi-check-circle me-1"></i>Complete payment & generate receipt</button></form></div></div></div><div class="col-lg-4"><div class="card mb-3"><div class="card-header">Payment summary</div><div class="card-body"><div class="d-flex justify-content-between mb-2"><span class="text-muted">Subtotal</span><span data-subtotal-out>₱0.00</span></div><div class="d-flex justify-content-between mb-3"><span class="text-muted">Discount</span><span>Applied at checkout</span></div><div class="border-top pt-3 d-flex justify-content-between"><strong>Total</strong><strong class="fs-4 text-success" data-total-out>₱0.00</strong></div><div class="small-muted mt-2">Prices are displayed in Philippine Peso (PHP).</div></div></div><div class="card"><div class="card-header">Quick checkout help</div><div class="card-body small text-muted"><p><i class="bi bi-1-circle me-2 text-success"></i>Choose a customer and service.</p><p><i class="bi bi-2-circle me-2 text-success"></i>Link an appointment to close the session, or add the therapist for a walk-in sale.</p><p><i class="bi bi-3-circle me-2 text-success"></i>Enter the amount received and complete payment.</p><p class="mb-0"><i class="bi bi-4-circle me-2 text-success"></i>Print the receipt from the confirmation or Transactions page.</p></div></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const a=document.getElementById('appointmentSelect');const c=document.getElementById('customerSelect');const s=document.getElementById('serviceSelect');const t=document.getElementById('therapistSelect');if(a)a.addEventListener('change',()=>{const o=a.selectedOptions[0];if(!a.value)return;c.value=o.dataset.customer||'';s.value=o.dataset.service||s.value;t.value=o.dataset.therapist||'';s.dispatchEvent(new Event('input',{bubbles:true}));});});</script>
<?php if(isset($_SESSION['last_receipt_id'])): $rid=(int)$_SESSION['last_receipt_id']; unset($_SESSION['last_receipt_id']);?><script>document.addEventListener('DOMContentLoaded',()=>{window.location.href=<?=json_encode(app_page_url('receipt',['id'=>$rid]))?>});</script><?php endif;?>
